css:
.sustaincareer-container {
    font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
    max-width: 1080px;
    margin: 0 auto;
    padding: 24px;
    color: #233329;
    background: linear-gradient(165deg, #f3f7ef 0%, #eef4ec 55%, #e8f1ea 100%);
    border-radius: 18px;
}

.sustaincareer-container * {
    box-sizing: border-box;
}

.sustaincareer-header {
    text-align: center;
    padding: 28px 22px 24px;
    background: linear-gradient(135deg, #1f5d3f 0%, #2f7d52 50%, #6aa84f 100%);
    color: #f3fbf2;
    border-radius: 16px;
    margin-bottom: 18px;
    box-shadow: 0 14px 34px rgba(31, 93, 63, 0.30);
}

.sustaincareer-header h1 {
    margin: 10px 0 10px;
    font-size: 2.4rem;
    font-weight: 800;
    letter-spacing: -0.5px;
    color: #ffffff;
}

.sustaincareer-header-tag {
    display: inline-block;
    font-size: 0.74rem;
    text-transform: uppercase;
    letter-spacing: 1.2px;
    font-weight: 700;
    color: #ffe6a8;
    background: rgba(255, 230, 168, 0.14);
    border: 1px solid rgba(255, 230, 168, 0.38);
    padding: 5px 14px;
    border-radius: 999px;
}

.sustaincareer-subtitle {
    margin: 0 auto;
    max-width: 840px;
    font-size: 1rem;
    line-height: 1.55;
    color: #dcefd8;
}

.sustaincareer-profiles {
    display: flex;
    align-items: stretch;
    gap: 12px;
    margin-bottom: 18px;
}

.sustaincareer-profile {
    flex: 1;
    background: #ffffff;
    border-radius: 14px;
    padding: 14px 18px;
    box-shadow: 0 4px 14px rgba(33, 51, 41, 0.08);
    display: flex;
    flex-direction: column;
    gap: 4px;
}

.sustaincareer-profile-early { border-left: 5px solid #4f9d6e; }
.sustaincareer-profile-mid { border-left: 5px solid #d99a2b; }
.sustaincareer-profile-senior { border-left: 5px solid #9d6b4f; }

.sustaincareer-profile-name {
    font-weight: 800;
    font-size: 1.05rem;
    color: #1f5d3f;
}

.sustaincareer-profile-early .sustaincareer-profile-name { color: #2f7d52; }
.sustaincareer-profile-mid .sustaincareer-profile-name { color: #b97d12; }
.sustaincareer-profile-senior .sustaincareer-profile-name { color: #8a5a3f; }

.sustaincareer-profile-meta {
    font-size: 0.82rem;
    color: #5a6b5e;
    line-height: 1.4;
}

.sustaincareer-period-counter {
    display: flex;
    align-items: center;
    gap: 8px;
    flex-wrap: wrap;
    font-size: 0.96rem;
    font-weight: 600;
    color: #41513f;
    margin-bottom: 16px;
    padding: 4px 4px;
}

.sustaincareer-period-counter #currentDay,
.sustaincareer-period-counter #maxPeriods {
    font-weight: 800;
    color: #2f7d52;
}

.sustaincareer-round-name {
    background: rgba(47, 125, 82, 0.14);
    color: #246b45;
    padding: 3px 12px;
    border-radius: 999px;
    font-size: 0.82rem;
    font-weight: 700;
    margin-left: 4px;
}

.sustaincareer-clock {
    margin-left: auto;
    font-size: 0.82rem;
    font-weight: 700;
    color: #a9760f;
    background: rgba(217, 154, 43, 0.14);
    border: 1px solid rgba(217, 154, 43, 0.30);
    padding: 4px 12px;
    border-radius: 999px;
}

.sustaincareer-status-cards {
    display: grid;
    grid-template-columns: repeat(4, 1fr);
    gap: 14px;
    margin-bottom: 16px;
}

.sustaincareer-status-card {
    background: #ffffff;
    border-radius: 14px;
    padding: 16px 16px 14px;
    box-shadow: 0 6px 16px rgba(33, 51, 41, 0.08);
    border-top: 4px solid #2f7d52;
}

.sustaincareer-card-csi { border-top-color: #1f5d3f; }
.sustaincareer-card-retention { border-top-color: #2f7d52; }
.sustaincareer-card-employ { border-top-color: #2f6fb0; }
.sustaincareer-card-wellbeing { border-top-color: #d99a2b; }

.sustaincareer-label {
    font-size: 0.74rem;
    text-transform: uppercase;
    letter-spacing: 0.6px;
    font-weight: 700;
    color: #6a7d6c;
}

.sustaincareer-value {
    font-size: 2.5rem;
    font-weight: 800;
    line-height: 1.1;
    margin: 4px 0 2px;
    color: #1f5d3f;
    font-variant-numeric: tabular-nums;
}

.sustaincareer-card-csi .sustaincareer-value { font-size: 2.9rem; color: #1f5d3f; }
.sustaincareer-card-retention .sustaincareer-value { color: #2f7d52; }
.sustaincareer-card-employ .sustaincareer-value { color: #2f6fb0; }
.sustaincareer-card-wellbeing .sustaincareer-value { color: #b97d12; }

.sustaincareer-sublabel {
    font-size: 0.76rem;
    color: #7a8a7c;
    line-height: 1.35;
}

.sustaincareer-card-csi.sustaincareer-csi-danger { border-top-color: #c5453c; }
.sustaincareer-card-csi.sustaincareer-csi-danger .sustaincareer-value { color: #c5453c; }
.sustaincareer-card-csi.sustaincareer-csi-good { border-top-color: #2f7d52; }
.sustaincareer-card-csi.sustaincareer-csi-good .sustaincareer-value { color: #2f7d52; }

.sustaincareer-budget-bar {
    display: flex;
    justify-content: space-between;
    align-items: center;
    background: #ffffff;
    border: 1px solid #d9e4da;
    color: #41513f;
    padding: 10px 18px;
    border-radius: 12px;
    margin-bottom: 12px;
    font-weight: 700;
    font-size: 0.92rem;
}

.sustaincareer-budget-bar #budgetDisplay {
    font-size: 1.05rem;
    color: #1f5d3f;
    font-weight: 800;
    font-variant-numeric: tabular-nums;
}

.sustaincareer-budget-bar.sustaincareer-budget-over #budgetDisplay { color: #c5453c; }

.sustaincareer-grievance-bar {
    display: flex;
    justify-content: space-between;
    align-items: center;
    background: #ffffff;
    border: 1px solid #d9e4da;
    color: #41513f;
    padding: 10px 18px;
    border-radius: 12px;
    margin-bottom: 18px;
    font-weight: 700;
    font-size: 0.92rem;
}

.sustaincareer-grievance-bar #grievanceDisplay {
    font-size: 1.05rem;
    letter-spacing: 0.3px;
    color: #c5453c;
    font-weight: 800;
}

.sustaincareer-grievance-bar.sustaincareer-grievance-low #grievanceDisplay { color: #2f7d52; }
.sustaincareer-grievance-bar.sustaincareer-grievance-mid #grievanceDisplay { color: #b97d12; }

.sustaincareer-briefing {
    display: flex;
    gap: 14px;
    background: #ffffff;
    border-left: 5px solid #2f7d52;
    border-radius: 12px;
    padding: 16px 18px;
    margin-bottom: 18px;
    box-shadow: 0 6px 16px rgba(33, 51, 41, 0.07);
}

.sustaincareer-briefing-icon {
    font-size: 1.8rem;
    line-height: 1;
}

.sustaincareer-briefing-title {
    font-weight: 800;
    font-size: 1.08rem;
    color: #1f5d3f;
    margin-bottom: 6px;
}

.sustaincareer-briefing-text {
    font-size: 0.95rem;
    line-height: 1.55;
    color: #3a4b3c;
}

.sustaincareer-briefing-text strong { color: #246b45; }
.sustaincareer-briefing-text em { color: #b97d12; font-style: italic; }

.sustaincareer-controls {
    background: #ffffff;
    border-radius: 14px;
    padding: 20px 22px;
    margin-bottom: 18px;
    box-shadow: 0 6px 16px rgba(33, 51, 41, 0.07);
}

.sustaincareer-controls h3 {
    margin: 0 0 14px;
    font-size: 1.12rem;
    font-weight: 800;
    color: #1f5d3f;
    border-bottom: 2px solid #e6ece5;
    padding-bottom: 8px;
}

.sustaincareer-panel label {
    display: block;
    font-weight: 700;
    font-size: 0.92rem;
    color: #2c3d2e;
    margin: 14px 0 6px;
}

.sustaincareer-container select,
.sustaincareer-container input[type="number"] {
    width: 100%;
    padding: 10px 12px;
    border: 1px solid #c4d2c6;
    border-radius: 9px;
    font-size: 0.92rem;
    background-color: #ffffff;
    color: #233329;
    transition: border-color 0.15s, box-shadow 0.15s;
}

.sustaincareer-container select:focus,
.sustaincareer-container input[type="number"]:focus {
    outline: none;
    border-color: #2f7d52;
    box-shadow: 0 0 0 3px rgba(47, 125, 82, 0.16);
}

.sustaincareer-container select option {
    background-color: #ffffff;
    color: #233329;
}

.sustaincareer-container input[type="range"] {
    width: 100%;
    margin: 8px 0 2px;
    accent-color: #2f7d52;
}

.sustaincareer-range-readout {
    font-size: 0.88rem;
    font-weight: 700;
    color: #41513f;
    margin-top: 4px;
}

.sustaincareer-range-readout span:nth-child(2) {
    color: #2f7d52;
    font-weight: 800;
}

.sustaincareer-hint {
    font-size: 0.8rem;
    color: #7a8a7c;
    margin-top: 6px;
    line-height: 1.4;
    font-style: italic;
}

.sustaincareer-container .btn {
    margin-top: 18px;
    font-weight: 700;
}

.sustaincareer-container .btn-primary {
    background: linear-gradient(135deg, #2f7d52 0%, #6aa84f 100%);
    border: none;
    color: #ffffff;
    padding: 11px 26px;
    border-radius: 9px;
    box-shadow: 0 8px 18px rgba(47, 125, 82, 0.32);
}

.sustaincareer-container .btn-primary:hover {
    filter: brightness(1.07);
}

.sustaincareer-container .btn-outline-secondary {
    margin-left: 10px;
    border: 1px solid #c4d2c6;
    color: #5a6b5e;
    background: transparent;
}

.sustaincareer-coach {
    background: linear-gradient(160deg, #1f5d3f 0%, #25503a 100%);
    color: #e3f1e5;
    border-radius: 14px;
    padding: 16px 20px;
    margin-bottom: 18px;
    box-shadow: 0 8px 20px rgba(31, 93, 63, 0.24);
}

.sustaincareer-coach-header {
    font-size: 0.78rem;
    text-transform: uppercase;
    letter-spacing: 1px;
    font-weight: 700;
    color: #ffe6a8;
    margin-bottom: 8px;
}

.sustaincareer-coach-body {
    font-size: 0.95rem;
    line-height: 1.55;
}

.sustaincareer-coach-body strong { color: #9fe0b4; }
.sustaincareer-coach-body em { color: #ffe6a8; font-style: italic; }

.sustaincareer-history,
.sustaincareer-chart {
    background: #ffffff;
    border-radius: 14px;
    padding: 18px 20px;
    margin-bottom: 18px;
    box-shadow: 0 6px 16px rgba(33, 51, 41, 0.07);
}

.sustaincareer-history h3,
.sustaincareer-chart h3 {
    margin: 0 0 14px;
    font-size: 1.08rem;
    font-weight: 800;
    color: #1f5d3f;
}

.sustaincareer-container table#usfHistoryTable {
    width: 100%;
    font-size: 0.88rem;
    color: #3a4b3c;
}

.sustaincareer-container table#usfHistoryTable th {
    background: #eef4ec;
    color: #246b45;
    font-weight: 700;
    text-transform: uppercase;
    font-size: 0.72rem;
    letter-spacing: 0.4px;
    padding: 8px 10px;
    border-bottom: 2px solid #d6e3d8;
}

.sustaincareer-container table#usfHistoryTable td {
    padding: 8px 10px;
    border-bottom: 1px solid #eef1ee;
    color: #3a4b3c;
}

.sustaincareer-container table#usfHistoryTable tr:nth-child(even) td {
    background: #f6faf5;
}

.sustaincareer-chart canvas {
    max-width: 100%;
}

@media (max-width: 768px) {
    .sustaincareer-container {
        padding: 14px;
    }
    .sustaincareer-header h1 {
        font-size: 1.7rem;
    }
    .sustaincareer-profiles {
        flex-direction: column;
    }
    .sustaincareer-status-cards {
        grid-template-columns: repeat(2, 1fr);
        gap: 10px;
    }
    .sustaincareer-value {
        font-size: 2rem;
    }
    .sustaincareer-card-csi .sustaincareer-value {
        font-size: 2.3rem;
    }
    .sustaincareer-clock {
        margin-left: 0;
    }
    .sustaincareer-period-counter {
        font-size: 0.88rem;
    }
    .sustaincareer-budget-bar,
    .sustaincareer-grievance-bar {
        flex-direction: column;
        gap: 4px;
        align-items: flex-start;
    }
    .sustaincareer-container .btn-outline-secondary {
        margin-left: 0;
        margin-top: 8px;
        display: block;
        width: 100%;
    }
}

/* ============================================================================
   Completion debrief (v1.1.0) — namespaced .scr-cm-*, append-only.
   Matches the sim's light sage/green palette. Rendered by
   SustainableCareersAdapter.formatCompletionMessage().
   ============================================================================ */
.scr-cm {
    font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
    color: #233329;
    background: linear-gradient(165deg, #f6faf3 0%, #eef4ec 60%, #e7f1e8 100%);
    border: 1px solid rgba(47, 125, 82, 0.28);
    border-radius: 16px; padding: 22px 24px 24px; max-width: 720px; margin: 8px auto;
    box-shadow: 0 12px 30px rgba(31, 93, 63, 0.14);
}
.scr-cm-head {
    display: flex; align-items: center; justify-content: space-between; gap: 16px; flex-wrap: wrap;
    border-bottom: 1px solid rgba(47, 125, 82, 0.22); padding-bottom: 14px; margin-bottom: 16px;
}
.scr-cm-verdict { font-size: 1.5rem; font-weight: 800; letter-spacing: -0.3px; line-height: 1.15; }
.scr-cm-good .scr-cm-verdict { color: #1f7a48; }
.scr-cm-mid  .scr-cm-verdict { color: #b97d12; }
.scr-cm-bad  .scr-cm-verdict { color: #c5453c; }
.scr-cm-score { display: flex; align-items: baseline; gap: 6px; white-space: nowrap; }
.scr-cm-score-num { font-size: 2.1rem; font-weight: 800; color: #1f5d3f; }
.scr-cm-score-max { font-size: 1rem; color: #6a7d6c; }
.scr-cm-grade {
    margin-left: 10px; font-size: 0.82rem; font-weight: 700; color: #1f5d3f;
    background: rgba(47, 125, 82, 0.12); border: 1px solid rgba(47, 125, 82, 0.30);
    padding: 3px 10px; border-radius: 999px;
}
.scr-cm-kpis { display: grid; grid-template-columns: repeat(4, 1fr); gap: 10px; margin-bottom: 14px; }
.scr-cm-kpi {
    background: #ffffff; border: 1px solid rgba(47, 125, 82, 0.18);
    border-radius: 12px; padding: 12px 10px; text-align: center;
}
.scr-cm-kpi-val { font-size: 1.35rem; font-weight: 800; color: #1f5d3f; }
.scr-cm-kpi-lbl { font-size: 0.72rem; text-transform: uppercase; letter-spacing: 0.5px; color: #6a7d6c; margin-top: 4px; }
.scr-cm-kpi.scr-cm-ok { border-color: rgba(47, 125, 82, 0.55); box-shadow: inset 0 0 0 1px rgba(47, 125, 82, 0.14); }
.scr-cm-kpi.scr-cm-no { border-color: rgba(197, 69, 60, 0.42); }
.scr-cm-rev { font-size: 0.95rem; color: #37483a; margin-bottom: 16px; }
.scr-cm-rev strong { color: #1f7a48; font-size: 1.05rem; }
.scr-cm-rev span { color: #6a7d6c; font-size: 0.85rem; }
.scr-cm-gates-h, .scr-cm-insights-h {
    font-size: 0.74rem; text-transform: uppercase; letter-spacing: 1px; font-weight: 700;
    color: #b97d12; margin: 6px 0 8px;
}
.scr-cm-gates { display: flex; flex-wrap: wrap; gap: 8px; margin-bottom: 16px; }
.scr-cm-chip { font-size: 0.8rem; font-weight: 600; padding: 5px 11px; border-radius: 999px; border: 1px solid transparent; }
.scr-cm-chip-ok { color: #ffffff; background: #2f7d52; }
.scr-cm-chip-no { color: #7a2a24; background: rgba(197, 69, 60, 0.14); border-color: rgba(197, 69, 60, 0.42); }
.scr-cm-insights { margin: 0; padding-left: 18px; }
.scr-cm-insights li { font-size: 0.92rem; line-height: 1.5; color: #37483a; margin-bottom: 8px; }
@media (max-width: 560px) {
    .scr-cm-kpis { grid-template-columns: repeat(2, 1fr); }
    .scr-cm-head { flex-direction: column; align-items: flex-start; }
}

