(function() {
    'use strict';

    class SustainableCareersAdapter extends USF.SimulationAdapter {
        constructor() {
            super();
            this.name = `Careers That Last`;
            this.version = `1.1.0`;

            this.ROUNDS = [
                { id: 1, titleKey: `briefing_title_r1`, textKey: `briefing_text_r1`, panelId: `round1Panel`, nameKey: `round_name_r1`, clockKey: `clock_r1` },
                { id: 2, titleKey: `briefing_title_r2`, textKey: `briefing_text_r2`, panelId: `round2Panel`, nameKey: `round_name_r2`, clockKey: `clock_r2` },
                { id: 3, titleKey: `briefing_title_r3`, textKey: `briefing_text_r3`, panelId: `round3Panel`, nameKey: `round_name_r3`, clockKey: `clock_r3` },
                { id: 4, titleKey: `briefing_title_r4`, textKey: `briefing_text_r4`, panelId: `round4Panel`, nameKey: `round_name_r4`, clockKey: `clock_r4` }
            ];

            // ---- Numbers reference card (Vlaamse TechWorks NV). ----
            this.BUDGET_CAP = 4.2;          // EUR 4.2M ring-fenced cycle ceiling
            this.START_CSI = 41;            // Career Sustainability Index baseline
            this.START_RETENTION = 83;      // 17% firm-wide turnover -> 83% stay
            this.START_EMPLOY = 48;         // skills currency vs labour market
            this.START_WELLBEING = 45;      // sickness absence up 2.1 pts YoY
            this.REPLACEMENT_COST = 55000;  // EUR per departure
            this.HEADCOUNT = 2600;          // total employees
            this.START_EARLY_SHARE = 78;    // % of budget to early-career today

            // ---- Concept truths (the modelled path). ----
            this.TRUE_MID = `orgstage`;
            this.TRUE_SENIOR = `marketskills`;
            this.TRUE_LENS = `lifecourse`;
        }

        initialize(state) {
            if (!state.domainState || Object.keys(state.domainState).length === 0) {
                state.domainState = {
                    csi: this.START_CSI,            // Career Sustainability Index (0–100)
                    retention: this.START_RETENTION, // firm-wide stay rate (%)
                    employ: this.START_EMPLOY,       // employability (0–100)
                    wellbeing: this.START_WELLBEING, // wellbeing (0–100)
                    grievance: 70,                   // works-council grievance risk 0–100 (lower safer)
                    budgetSpent: 0,                  // EUR M committed (rounds 3–4)
                    earlyShare: this.START_EARLY_SHARE, // last committed early-career share (%)
                    baseline: this.START_CSI,        // learner-set CSI baseline
                    netSaving: 0,                    // EUR M annual turnover saving (derived)

                    // ---- Sticky run-defining penalty flags (set on commit, never auto-cleared). ----
                    tunnelVisionRun: false,  // kept the budget on early-career (HEADLINE anti-pattern)
                    trainingAllRun: false,   // answered org/life-stage problems with training
                    hoardingRun: false,      // withheld employability for fear of attrition
                    perksRun: false,         // perks over paths/meaning
                    zeroSumRun: false,       // rebalanced without redesigning early-career
                    lifeCourseRun: false,    // framed and acted on the whole life-course

                    csiHistory: [this.START_CSI],
                    retentionHistory: [this.START_RETENTION],
                    employHistory: [this.START_EMPLOY],
                    wellbeingHistory: [this.START_WELLBEING],
                    lastCoach: ``
                };
            }
            if (!state.decisions || Object.keys(state.decisions).length === 0) {
                // Seeded defaults lean toward the classic errors — a blind
                // click-through must NOT auto-win.
                state.decisions = {
                    midDiagnosis: `skills`,
                    seniorDiagnosis: `attitude`,
                    lens: `hipo`,
                    baseline: 41,
                    earlyIntervention: `moretraining`,
                    midIntervention: `training`,
                    seniorIntervention: `hoard`,
                    balance: 50,
                    earlyShare: 78,
                    midShare: 50,
                    protect: `nothing`,
                    risk: `earlyperks`,
                    complication: `stoptraining`,
                    reallocate: `hold`,
                    system: `none`,
                    pitch: 50
                };
            }
            this._updateBriefing(state);
        }

        validateDecisions(decisions) {
            const state = window.mySimulation.state;
            const round = state.currentPeriod || 1;
            const warn = (k) => window.mySimulation.uiManager.showNotification(window.mySimulation.t(k), `warning`);

            if (round === 1) {
                const md = document.getElementById(`midDiagnosisInput`);
                const sd = document.getElementById(`seniorDiagnosisInput`);
                const ln = document.getElementById(`lensInput`);
                const bl = document.getElementById(`baselineInput`);
                if (md) decisions.midDiagnosis = md.value;
                if (sd) decisions.seniorDiagnosis = sd.value;
                if (ln) decisions.lens = ln.value;
                if (bl) decisions.baseline = parseInt(bl.value, 10);
                if (!Number.isFinite(decisions.baseline) || decisions.baseline < 0 || decisions.baseline > 100) {
                    warn(`warn_baseline_range`); return false;
                }
            } else if (round === 2) {
                const ei = document.getElementById(`earlyInterventionInput`);
                const mi = document.getElementById(`midInterventionInput`);
                const si = document.getElementById(`seniorInterventionInput`);
                const ba = document.getElementById(`balanceInput`);
                if (ei) decisions.earlyIntervention = ei.value;
                if (mi) decisions.midIntervention = mi.value;
                if (si) decisions.seniorIntervention = si.value;
                if (ba) decisions.balance = parseInt(ba.value, 10);
                if (!Number.isFinite(decisions.balance) || decisions.balance < 0 || decisions.balance > 100) {
                    warn(`warn_balance_range`); return false;
                }
            } else if (round === 3) {
                const es = document.getElementById(`earlyShareInput`);
                const ms = document.getElementById(`midShareInput`);
                const pr = document.getElementById(`protectInput`);
                const rk = document.getElementById(`riskInput`);
                if (es) decisions.earlyShare = parseInt(es.value, 10);
                if (ms) decisions.midShare = parseInt(ms.value, 10);
                if (pr) decisions.protect = pr.value;
                if (rk) decisions.risk = rk.value;
                if (!Number.isFinite(decisions.earlyShare) || decisions.earlyShare < 20 || decisions.earlyShare > 78) {
                    warn(`warn_share_range`); return false;
                }
                if (!Number.isFinite(decisions.midShare) || decisions.midShare < 0 || decisions.midShare > 100) {
                    warn(`warn_midshare_range`); return false;
                }
            } else if (round === 4) {
                const co = document.getElementById(`complicationInput`);
                const re = document.getElementById(`reallocateInput`);
                const sy = document.getElementById(`systemInput`);
                const pi = document.getElementById(`pitchInput`);
                if (co) decisions.complication = co.value;
                if (re) decisions.reallocate = re.value;
                if (sy) decisions.system = sy.value;
                if (pi) decisions.pitch = parseInt(pi.value, 10);
                if (!Number.isFinite(decisions.pitch) || decisions.pitch < 0 || decisions.pitch > 100) {
                    warn(`warn_pitch_range`); return false;
                }
            }
            return true;
        }

        calculateResults(state) {
            const d = state.decisions;
            const ds = state.domainState;
            const round = state.currentPeriod;

            let csiDelta = 0, retentionDelta = 0, employDelta = 0, wellbeingDelta = 0, grievanceDelta = 0;
            let coachKey = `coach_default`;
            let summaryKey = `sum_default`;

            if (round === 1) {
                // ---- Diagnose: locate each breakage at the right interface level. ----
                ds.baseline = d.baseline;

                // Mid-career: an organisation & life-stage problem, NOT a skills gap.
                switch (d.midDiagnosis) {
                    case `orgstage`: csiDelta += 2; grievanceDelta -= 4; break;
                    case `skills`: grievanceDelta += 4; coachKey = `coach_r1_midskills`; break; // mis-diagnosis seeds the training trap
                    case `pay`: grievanceDelta += 3; coachKey = `coach_r1_midpay`; break;
                }

                // Senior: a labour-market & organisation problem (obsolescing skills, low employability).
                switch (d.seniorDiagnosis) {
                    case `marketskills`: csiDelta += 2; grievanceDelta -= 4; break;
                    case `attitude`: grievanceDelta += 4; coachKey = `coach_r1_seniorattitude`; break;
                    case `leave`: grievanceDelta += 5; coachKey = `coach_r1_seniorloyal`; break;
                }

                // The framing lens — the headline diagnosis.
                switch (d.lens) {
                    case `lifecourse`:
                        ds.lifeCourseRun = true;
                        csiDelta += 4; grievanceDelta -= 6;
                        if (d.midDiagnosis === `orgstage` && d.seniorDiagnosis === `marketskills`) coachKey = `coach_r1_sharp`;
                        break;
                    case `hipo`:
                        ds.tunnelVisionRun = true; // HEADLINE anti-pattern declared at the diagnosis stage
                        csiDelta -= 3; grievanceDelta += 7;
                        coachKey = `coach_r1_hipo`;
                        break;
                    case `perks`:
                        ds.perksRun = true;
                        csiDelta -= 1; grievanceDelta += 4;
                        coachKey = `coach_r1_perks`;
                        break;
                }

                // Honest baseline: a wildly inflated one is itself a red flag.
                if (d.baseline > 60) { grievanceDelta += 3; if (coachKey === `coach_default`) coachKey = `coach_r1_inflated`; }

                summaryKey = (d.midDiagnosis === `orgstage` && d.seniorDiagnosis === `marketskills` && d.lens === `lifecourse`) ? `sum_r1_good` : `sum_r1_weak`;
            } else if (round === 2) {
                // ---- Plan: match each intervention to the right interface level. ----
                const balance = d.balance / 100;

                // Early-career: well-developed but burning out -> workload guardrails + paths.
                switch (d.earlyIntervention) {
                    case `workload`: wellbeingDelta += 7; csiDelta += 4; retentionDelta += 2; break;
                    case `moretraining`: ds.tunnelVisionRun = true; wellbeingDelta -= 3; csiDelta -= 2; coachKey = `coach_r2_earlymore`; break;
                    case `ignore`: wellbeingDelta -= 4; retentionDelta -= 2; coachKey = `coach_r2_earlyignore`; break;
                }

                // Mid-career: a path + caregiving relief (mobility), NOT courses, NOT a perk.
                switch (d.midIntervention) {
                    case `mobility`: csiDelta += 8; retentionDelta += 5; wellbeingDelta += 4; employDelta += 3; grievanceDelta -= 6; break;
                    case `training`: ds.trainingAllRun = true; csiDelta -= 3; retentionDelta -= 1; coachKey = `coach_r2_midtraining`; break;
                    case `wellnessapp`: ds.perksRun = true; wellbeingDelta += 1; csiDelta -= 2; coachKey = `coach_r2_midperk`; break;
                }

                // Senior: the employability paradox -> reskilling + meaning beats hoarding/perks.
                switch (d.seniorIntervention) {
                    case `reskill`: employDelta += 10; csiDelta += 7; wellbeingDelta += 5; retentionDelta += 3; grievanceDelta -= 6; break;
                    case `hoard`: ds.hoardingRun = true; employDelta -= 5; wellbeingDelta -= 4; csiDelta -= 4; grievanceDelta += 6; coachKey = `coach_r2_seniorhoard`; break;
                    case `sabbatical`: ds.perksRun = true; wellbeingDelta += 2; employDelta -= 2; csiDelta -= 1; coachKey = `coach_r2_seniorperk`; break;
                }

                // Deliberate employability–wellbeing balance is the craft (jointly necessary).
                if (balance >= 0.6 && balance <= 0.85) { csiDelta += 4; wellbeingDelta += 2; employDelta += 2; }
                else if (balance <= 0.25) { wellbeingDelta -= 3; coachKey = `coach_r2_unbalanced`; } // maximising one leg
                else if (balance >= 0.95) { employDelta += 1; wellbeingDelta -= 2; } // stretch load with no guardrail

                if (d.earlyIntervention === `workload` && d.midIntervention === `mobility` && d.seniorIntervention === `reskill`) {
                    coachKey = `coach_r2_matched`;
                }

                summaryKey = (d.midIntervention === `mobility` && d.seniorIntervention === `reskill` && d.earlyIntervention === `workload`) ? `sum_r2_good` :
                             (d.midIntervention === `training` ? `sum_r2_training` :
                             (d.seniorIntervention === `hoard` ? `sum_r2_hoard` :
                             ((d.midIntervention === `wellnessapp` || d.seniorIntervention === `sabbatical`) ? `sum_r2_perks` : `sum_r2_weak`)));
            } else if (round === 3) {
                // ---- Decide: allocate the full EUR 4.2M under the hard ceiling. ----
                ds.earlyShare = d.earlyShare;
                ds.budgetSpent = this.BUDGET_CAP; // the full cycle budget is committed this round

                const earlyFrac = d.earlyShare / 100;
                const remainder = 1 - earlyFrac;
                const midFrac = remainder * (d.midShare / 100);
                const seniorFrac = remainder * (1 - d.midShare / 100);

                // The politically hard rebalancing away from early-career's 78% share.
                if (d.earlyShare >= 70) {
                    // HEADLINE anti-pattern: budget still serves the third that was already fine.
                    ds.tunnelVisionRun = true;
                    csiDelta -= 6; grievanceDelta += 12; retentionDelta -= 3;
                    coachKey = `coach_r3_tunnel`;
                } else if (d.earlyShare >= 55) {
                    csiDelta += 1; grievanceDelta -= 1;
                } else if (d.earlyShare >= 35) {
                    // A credible life-course rebalance.
                    csiDelta += 7; grievanceDelta -= 10;
                } else {
                    // Over-corrected: starves the early-career third (its own new neglect).
                    csiDelta += 2; grievanceDelta -= 4; retentionDelta -= 2; coachKey = `coach_r3_overcorrect`;
                }

                // Fund the neglected groups: mid & senior must get a real share.
                if (midFrac >= 0.18) { csiDelta += 3; retentionDelta += 3; grievanceDelta -= 3; }
                else { grievanceDelta += 4; }
                if (seniorFrac >= 0.18) { csiDelta += 3; employDelta += 4; wellbeingDelta += 2; grievanceDelta -= 3; }
                else { grievanceDelta += 5; employDelta -= 2; if (coachKey === `coach_default`) coachKey = `coach_r3_seniorstarved`; }

                // Protect early-career while rebalancing: redesign, not a zero-sum raid.
                switch (d.protect) {
                    case `redesign`: csiDelta += 4; retentionDelta += 2; wellbeingDelta += 1; break;
                    case `hope`: retentionDelta -= 2; if (d.earlyShare < 70) { ds.zeroSumRun = true; } break;
                    case `nothing`:
                        retentionDelta -= 3;
                        if (d.earlyShare < 70) { ds.zeroSumRun = true; coachKey = `coach_r3_zerosum`; } // cut without a redesign
                        break;
                }

                // Name the largest under-funded risk correctly.
                switch (d.risk) {
                    case `seniormid`: grievanceDelta -= 5; csiDelta += 2; break;
                    case `earlyperks`: grievanceDelta += 4; coachKey = `coach_r3_wrongrisk`; break;
                    case `exec`: grievanceDelta += 3; break;
                }

                if (d.earlyShare >= 35 && d.earlyShare < 55 && midFrac >= 0.18 && seniorFrac >= 0.18 && d.protect === `redesign`) {
                    coachKey = `coach_r3_lifecourse`;
                }

                summaryKey = (d.earlyShare >= 35 && d.earlyShare < 55 && midFrac >= 0.18 && seniorFrac >= 0.18 && d.protect === `redesign`) ? `sum_r3_good` :
                             (d.earlyShare >= 70 ? `sum_r3_tunnel` :
                             (ds.zeroSumRun ? `sum_r3_zerosum` :
                             (seniorFrac < 0.18 ? `sum_r3_starved` : `sum_r3_weak`)));
            } else if (round === 4) {
                // ---- Recover: complication, reallocation, standing system, board pitch. ----

                // Complication: a competitor poaches the upskilled mid-career cohort.
                switch (d.complication) {
                    case `pathmeaning`: retentionDelta += 6; csiDelta += 5; employDelta += 2; grievanceDelta -= 4; break;
                    case `stoptraining`: ds.hoardingRun = true; employDelta -= 6; csiDelta -= 4; wellbeingDelta -= 2; coachKey = `coach_r4_stoptraining`; break;
                    case `counteroffer`: retentionDelta += 1; csiDelta -= 2; coachKey = `coach_r4_counteroffer`; break;
                }

                // Reallocate mid-cycle: fund what works, fix or cut what does not.
                switch (d.reallocate) {
                    case `fundwhatworks`: csiDelta += 6; retentionDelta += 3; employDelta += 2; break;
                    case `cutworking`: csiDelta -= 5; retentionDelta -= 4; grievanceDelta += 5; coachKey = `coach_r4_cutworking`; break;
                    case `hold`: csiDelta -= 1; coachKey = `coach_r4_hold`; break;
                }

                // The standing system that outlasts the budget cycle.
                switch (d.system) {
                    case `standing`: csiDelta += 6; wellbeingDelta += 3; employDelta += 3; grievanceDelta -= 6; break;
                    case `survey`: csiDelta += 1; grievanceDelta -= 1; coachKey = `coach_r4_survey`; break;
                    case `none`: csiDelta -= 3; grievanceDelta += 5; coachKey = `coach_r4_nosystem`; break;
                }

                // The board pitch — conviction in the life-course case.
                if (d.pitch >= 60) { csiDelta += 2; grievanceDelta -= 2; }
                else if (d.pitch <= 25) { csiDelta -= 1; grievanceDelta += 2; }

                if (d.complication === `pathmeaning` && d.reallocate === `fundwhatworks` && d.system === `standing`) {
                    coachKey = `coach_r4_board`;
                }

                summaryKey = (d.complication === `pathmeaning` && d.reallocate === `fundwhatworks` && d.system === `standing`) ? `sum_r4_good` : `sum_r4_weak`;
            }

            // ---- Apply raw deltas (clamped). ----
            ds.csi = Math.max(0, Math.min(100, Math.round((ds.csi + csiDelta) * 10) / 10));
            ds.employ = Math.max(0, Math.min(100, Math.round((ds.employ + employDelta) * 10) / 10));
            ds.wellbeing = Math.max(0, Math.min(100, Math.round((ds.wellbeing + wellbeingDelta) * 10) / 10));
            ds.grievance = Math.max(0, Math.min(100, Math.round(ds.grievance + grievanceDelta)));

            // ---- Retention is co-produced: it rises with the triad and falls with grievance risk. ----
            const triad = (ds.csi + ds.employ + ds.wellbeing) / 3;        // 0..100
            const triadPull = (triad - 50) * 0.10;                         // toward/away from health
            const grievanceDrag = (ds.grievance - 50) * 0.06;             // high grievance -> exits
            ds.retention = Math.max(0, Math.min(100, Math.round((ds.retention + retentionDelta + triadPull - grievanceDrag) * 10) / 10));

            // ---- Sticky penalty flags GATE the top KPIs (a later good round cannot wash them out). ----
            if (ds.tunnelVisionRun) { ds.csi = Math.min(ds.csi, 58); ds.grievance = Math.max(ds.grievance, 45); }
            if (ds.hoardingRun) { ds.employ = Math.min(ds.employ, 55); ds.csi = Math.min(ds.csi, 66); }
            if (ds.trainingAllRun) { ds.csi = Math.min(ds.csi, 68); ds.grievance = Math.max(ds.grievance, 40); }
            if (ds.zeroSumRun) { ds.retention = Math.min(ds.retention, 86); ds.csi = Math.min(ds.csi, 70); }
            if (ds.perksRun && !ds.lifeCourseRun) { ds.csi = Math.min(ds.csi, 64); }

            // ---- Net annual turnover saving vs. the 17% run-rate (business case in EUR). ----
            const departuresAvoided = Math.round(this.HEADCOUNT * ((ds.retention - this.START_RETENTION) / 100));
            ds.netSaving = Math.round((departuresAvoided * this.REPLACEMENT_COST / 1000000) * 10) / 10; // EUR M, 1 dp

            ds.csiHistory.push(ds.csi);
            ds.retentionHistory.push(ds.retention);
            ds.employHistory.push(ds.employ);
            ds.wellbeingHistory.push(ds.wellbeing);

            // ---- Persist the composite where the gradebook / AGS + history readers look ----
            // Framework contract (results_utils.php): express_resolveDomainScore reads
            // domainState.performance.overallScore first, then a top-level score; and
            // express_extractHistory reads history[].domainState.performance.overallScore.
            // addToHistory() deep-clones domainState into each snapshot, so writing it here
            // lands the per-period score in the gradebook by construction.
            const composite = this._composite(ds);
            ds.performance = { overallScore: composite, grade: this._gradeLetter(composite) };
            ds.score = composite;

            const coachMsg = window.mySimulation.t(coachKey);
            ds.lastCoach = coachMsg;
            const coachEl = document.getElementById(`coachText`);
            if (coachEl) coachEl.innerHTML = coachMsg;

            const self = this;
            setTimeout(function() {
                self._updateBriefing({ currentPeriod: state.currentPeriod + 1 });
            }, 500);

            return {
                period: state.currentPeriod,
                csi: ds.csi,
                csiDelta: Math.round(csiDelta * 10) / 10,
                retention: ds.retention,
                employ: ds.employ,
                wellbeing: ds.wellbeing,
                grievance: ds.grievance,
                budgetSpent: ds.budgetSpent,
                netSaving: ds.netSaving,
                tunnelVisionRun: ds.tunnelVisionRun,
                score: composite,
                overallScore: composite,
                summary: window.mySimulation.t(summaryKey),
                coach: coachMsg
            };
        }

        _grievanceLabel(v) {
            const t = window.mySimulation ? window.mySimulation.t.bind(window.mySimulation) : (k) => k;
            if (v >= 60) return t(`grievance_high`);
            if (v >= 35) return t(`grievance_mid`);
            return t(`grievance_low`);
        }

        _fmtBudget(spent) {
            const lang = (window.mySimulation && window.mySimulation.language) ? window.mySimulation.language : `en`;
            const fmt = (n) => {
                const s = n.toFixed(2);
                return lang === `es` ? s.replace(`.`, `,`) : s;
            };
            return `€${fmt(Number(spent))}M / €${fmt(this.BUDGET_CAP)}M`;
        }

        setupUI(uiManager) {
            uiManager.bind(`currentDay`, `currentPeriod`);
            uiManager.bind(`maxPeriods`, `maxPeriods`);

            const self = this;

            uiManager.bind(`csiDisplay`, `domainState.csi`, (v) => {
                const n = Math.round(Number(v));
                const card = document.querySelector(`.sustaincareer-card-csi`);
                if (card) {
                    card.classList.toggle(`sustaincareer-csi-danger`, n < 50);
                    card.classList.toggle(`sustaincareer-csi-good`, n >= 70);
                }
                return `${n}`;
            });

            uiManager.bind(`retentionDisplay`, `domainState.retention`, (v) => `${Math.round(Number(v))}%`);
            uiManager.bind(`employDisplay`, `domainState.employ`, (v) => `${Math.round(Number(v))}`);
            uiManager.bind(`wellbeingDisplay`, `domainState.wellbeing`, (v) => `${Math.round(Number(v))}`);

            uiManager.bind(`budgetDisplay`, `domainState.budgetSpent`, (v) => {
                const bar = document.querySelector(`.sustaincareer-budget-bar`);
                if (bar) bar.classList.toggle(`sustaincareer-budget-over`, Number(v) > self.BUDGET_CAP + 0.001);
                return self._fmtBudget(v);
            });

            uiManager.bind(`grievanceDisplay`, `domainState.grievance`, (v) => {
                const n = Number(v);
                const bar = document.querySelector(`.sustaincareer-grievance-bar`);
                if (bar) {
                    bar.classList.toggle(`sustaincareer-grievance-low`, n < 35);
                    bar.classList.toggle(`sustaincareer-grievance-mid`, n >= 35 && n < 60);
                }
                return self._grievanceLabel(n);
            });

            // Balance slider readout (Round 2).
            const ba = document.getElementById(`balanceInput`);
            const baReadout = document.getElementById(`balanceReadout`);
            if (ba && baReadout) {
                baReadout.textContent = ba.value;
                ba.addEventListener(`input`, function() { baReadout.textContent = ba.value; });
            }

            // Early-share slider readout (Round 3).
            const es = document.getElementById(`earlyShareInput`);
            const esReadout = document.getElementById(`earlyShareReadout`);
            if (es && esReadout) {
                esReadout.textContent = es.value;
                es.addEventListener(`input`, function() { esReadout.textContent = es.value; });
            }

            // Mid-share slider readout (Round 3).
            const ms = document.getElementById(`midShareInput`);
            const msReadout = document.getElementById(`midShareReadout`);
            if (ms && msReadout) {
                msReadout.textContent = ms.value;
                ms.addEventListener(`input`, function() { msReadout.textContent = ms.value; });
            }
        }

        // Composite — the VERBATIM v1.0.0 scorecard (CSI weighted heaviest), factored out so
        // calculateResults() can persist the same value every period that getPerformanceSummary()
        // reports at completion. Scoring is unchanged; this is a refactor, not a re-tune. (The
        // run-defining flags cap the underlying KPIs in calculateResults, so their effect is
        // already baked into ds before this runs — the composite has no separate caps.)
        _composite(ds) {
            const csi = Math.round(ds.csi);
            const retention = Math.round(ds.retention);
            const employ = Math.round(ds.employ);
            const wellbeing = Math.round(ds.wellbeing);
            return Math.round(csi * 0.34 + retention * 0.24 + employ * 0.21 + wellbeing * 0.21);
        }

        // Letter grade surfaced to the gradebook / AGS via domainState.performance.grade.
        _gradeLetter(c) {
            if (c >= 85) return `A`;
            if (c >= 70) return `B`;
            if (c >= 58) return `C`;
            if (c >= 45) return `D`;
            return `F`;
        }

        // Localize the internal (English) verdict tier id. The English id stays the stable key
        // the scoring logic keys on; the label is resolved for display only.
        _gradeLabel(id) {
            const t = (window.mySimulation && typeof window.mySimulation.t === `function`)
                ? window.mySimulation.t.bind(window.mySimulation) : (k) => k;
            const map = {
                'Careers Made Sustainable':    `verdict_sustainable`,
                'Sustainability Gaining':      `verdict_gaining`,
                'High-Potential Tunnel Vision': `verdict_tunnel`,
                'Employability Hoarded':       `verdict_hoarded`,
                'Training as a Cure-All':      `verdict_training`,
                'Zero-Sum Rebalance':          `verdict_zerosum`,
                'Perks Over Paths':            `verdict_perks`,
                'Mixed Outcome':               `verdict_mixed`,
                'Sustainability Debt':         `verdict_debt`
            };
            return map[id] ? t(map[id]) : id;
        }

        getChartConfig() {
            // Guarded translator: localize chart chrome, fall back to English literals if the
            // framework isn't ready when the config is first built.
            const t = (window.mySimulation && typeof window.mySimulation.t === `function`)
                ? window.mySimulation.t.bind(window.mySimulation) : null;
            const L = (k, fallback) => (t ? t(k) : fallback);
            return {
                careerChart: {
                    type: `line`,
                    data: {
                        labels: [],
                        datasets: [
                            {
                                label: L(`chart_ds_csi`, `Career Sustainability Index`),
                                data: [],
                                borderColor: `#1f5d3f`,
                                backgroundColor: `rgba(31,93,63,0.12)`,
                                borderWidth: 3,
                                fill: true,
                                tension: 0.25,
                                pointRadius: 5,
                                pointBackgroundColor: `#1f5d3f`,
                                yAxisID: `y`
                            },
                            {
                                label: L(`chart_ds_retention`, `Retention (%)`),
                                data: [],
                                borderColor: `#2f7d52`,
                                backgroundColor: `rgba(47,125,82,0.10)`,
                                borderWidth: 2,
                                fill: false,
                                tension: 0.25,
                                pointRadius: 4,
                                pointBackgroundColor: `#2f7d52`,
                                yAxisID: `y`
                            },
                            {
                                label: L(`chart_ds_employ`, `Employability`),
                                data: [],
                                borderColor: `#2f6fb0`,
                                backgroundColor: `rgba(47,111,176,0.08)`,
                                borderWidth: 2,
                                borderDash: [5, 4],
                                fill: false,
                                tension: 0.25,
                                pointRadius: 4,
                                pointBackgroundColor: `#2f6fb0`,
                                yAxisID: `y`
                            },
                            {
                                label: L(`chart_ds_wellbeing`, `Wellbeing`),
                                data: [],
                                borderColor: `#d99a2b`,
                                backgroundColor: `rgba(217,154,43,0.08)`,
                                borderWidth: 2,
                                borderDash: [2, 3],
                                fill: false,
                                tension: 0.25,
                                pointRadius: 4,
                                pointBackgroundColor: `#d99a2b`,
                                yAxisID: `y`
                            }
                        ]
                    },
                    options: {
                        responsive: true,
                        maintainAspectRatio: false,
                        plugins: {
                            legend: { position: `bottom`, labels: { color: `#41513f`, boxWidth: 14 } },
                            title: { display: false }
                        },
                        scales: {
                            y: {
                                beginAtZero: true, max: 100, position: `left`,
                                ticks: { color: `#6a7d6c` }, grid: { color: `rgba(33,51,41,0.06)` },
                                title: { display: true, text: L(`chart_axis_index`, `0–100`), color: `#6a7d6c` }
                            },
                            x: {
                                ticks: { color: `#6a7d6c` }, grid: { color: `rgba(33,51,41,0.04)` },
                                title: { display: true, text: L(`chart_axis_round`, `Round`), color: `#6a7d6c` }
                            }
                        }
                    }
                }
            };
        }

        getChartData(state) {
            const ds = state.domainState;
            const labels = ds.csiHistory.map((_, i) => (i === 0 ? window.mySimulation.t(`chart_start`) : `R` + i));
            return {
                careerChart: {
                    labels: labels,
                    datasets: [
                        { data: ds.csiHistory.map((v) => Math.round(v)) },
                        { data: ds.retentionHistory.map((v) => Math.round(v)) },
                        { data: ds.employHistory.map((v) => Math.round(v)) },
                        { data: ds.wellbeingHistory.map((v) => Math.round(v)) }
                    ]
                }
            };
        }

        getPerformanceSummary(history) {
            if (!history.length) return {};
            const ds = window.mySimulation.state.domainState;
            const csi = Math.round(ds.csi);
            const retention = Math.round(ds.retention);
            const employ = Math.round(ds.employ);
            const wellbeing = Math.round(ds.wellbeing);
            const netSaving = ds.netSaving;

            // Composite scorecard — CSI weighted heaviest (the board's headline KPI). Shares the
            // _composite(ds) helper that calculateResults() persists every period, so the
            // completion composite == the last period's persisted score by construction.
            const composite = this._composite(ds);

            const improved = csi >= (ds.baseline + 12);   // measurable gain vs. the set baseline
            const retainedWell = retention >= 88;          // turnover pulled toward ~12% or better
            const employable = employ >= 62;
            const well = wellbeing >= 60;
            const lowGrievance = ds.grievance < 40;

            // Run-defining pattern (sticky errors decide the headline, not the last round).
            let pattern = `mixed`;
            if (ds.tunnelVisionRun) pattern = `tunnel`;
            else if (ds.hoardingRun) pattern = `hoarding`;
            else if (ds.trainingAllRun) pattern = `training`;
            else if (ds.zeroSumRun) pattern = `zerosum`;
            else if (ds.perksRun && !ds.lifeCourseRun) pattern = `perks`;
            else if (ds.lifeCourseRun && improved && retainedWell && employable && well) pattern = `sustainable`;

            // ---- Verdict. The HEADLINE anti-patterns can NEVER reach the top, however
            //      well the remaining rounds are played (sticky run-defining flags gate it).
            //      "Perks over paths" counts as run-defining only when NOT redeemed by a
            //      genuine whole-life-course frame (mirrors the CSI cap and the pattern logic). ----
            const perksRun = ds.perksRun && !ds.lifeCourseRun;
            let performance = `Sustainability Debt`;
            const topEligible = !ds.tunnelVisionRun && !ds.hoardingRun && !ds.trainingAllRun && !ds.zeroSumRun && !perksRun;
            if (topEligible && improved && retainedWell && employable && well && lowGrievance && composite >= 74) {
                performance = `Careers Made Sustainable`;
            } else if (topEligible && improved && (retainedWell || employable) && composite >= 62) {
                performance = `Sustainability Gaining`;
            } else if (ds.tunnelVisionRun) {
                performance = `High-Potential Tunnel Vision`;
            } else if (ds.hoardingRun) {
                performance = `Employability Hoarded`;
            } else if (ds.trainingAllRun) {
                performance = `Training as a Cure-All`;
            } else if (ds.zeroSumRun) {
                performance = `Zero-Sum Rebalance`;
            } else if (perksRun) {
                performance = `Perks Over Paths`;
            } else if (composite >= 55) {
                performance = `Mixed Outcome`;
            }

            const insights = [];
            if (pattern === `sustainable` && performance === `Careers Made Sustainable`) insights.push(window.mySimulation.t(`insight_sustainable`));
            else if (pattern === `tunnel`) insights.push(window.mySimulation.t(`insight_tunnel`));
            else if (pattern === `hoarding`) insights.push(window.mySimulation.t(`insight_hoarding`));
            else if (pattern === `training`) insights.push(window.mySimulation.t(`insight_training`));
            else if (pattern === `zerosum`) insights.push(window.mySimulation.t(`insight_zerosum`));
            else if (pattern === `perks`) insights.push(window.mySimulation.t(`insight_perks`));
            else insights.push(window.mySimulation.t(`insight_mixed`));

            if (!improved) insights.push(window.mySimulation.t(`insight_csi_flat`));
            if (employ < 55) insights.push(window.mySimulation.t(`insight_employ_low`));
            if (wellbeing < 50) insights.push(window.mySimulation.t(`insight_wellbeing_low`));
            if (ds.grievance >= 60) insights.push(window.mySimulation.t(`insight_grievance`));
            if (netSaving > 0) insights.push(window.mySimulation.t(`insight_saving`));
            else if (retention < this.START_RETENTION) insights.push(window.mySimulation.t(`insight_saving_neg`));

            return {
                csi: csi,
                baseline: ds.baseline,
                retention: retention,
                employ: employ,
                wellbeing: wellbeing,
                netSaving: netSaving,
                improved: improved,
                retainedWell: retainedWell,
                employable: employable,
                well: well,
                pattern: pattern,
                lowGrievance: lowGrievance,
                composite: composite,
                grade: this._gradeLetter(composite),
                performance: this._gradeLabel(performance),
                performanceId: performance,
                insights: insights
            };
        }

        // Rich, localized board debrief. Without this override the framework falls through to
        // the base "You completed N periods." stub and discards the composite, verdict, KPIs and
        // insights this sim already computes. Self-contained, namespaced (.scr-cm-*) markup.
        formatCompletionMessage(summary) {
            const t = (window.mySimulation && typeof window.mySimulation.t === `function`)
                ? window.mySimulation.t.bind(window.mySimulation) : (k) => k;
            const s = summary || {};
            const esc = (v) => String(v == null ? `` : v).replace(/[&<>]/g, (c) => ({ '&': `&amp;`, '<': `&lt;`, '>': `&gt;` }[c]));
            const lang = (window.mySimulation && window.mySimulation.language) ? window.mySimulation.language : `en`;
            const num1 = (v) => { const x = (Math.round(Number(v) * 10) / 10).toFixed(1); return lang === `es` ? x.replace(`.`, `,`) : x; };

            const composite = Math.round(Number(s.composite) || 0);
            const grade = esc(s.grade || this._gradeLetter(composite));
            const verdict = esc(s.performance || ``);
            const id = s.performanceId || ``;
            const tone = (id === `Careers Made Sustainable`) ? `good`
                : (id === `Sustainability Gaining` || id === `Mixed Outcome`) ? `mid` : `bad`;

            const saving = Number(s.netSaving) || 0;
            const savingStr = (saving >= 0 ? `€` : `−€`) + num1(Math.abs(saving)) + `M`;
            const kpi = (label, value, ok) =>
                `<div class="scr-cm-kpi ${ok ? `scr-cm-ok` : `scr-cm-no`}"><div class="scr-cm-kpi-val">${value}</div><div class="scr-cm-kpi-lbl">${label}</div></div>`;
            const chip = (ok, label) =>
                `<span class="scr-cm-chip ${ok ? `scr-cm-chip-ok` : `scr-cm-chip-no`}">${ok ? `✓` : `✕`} ${label} · ${ok ? esc(t(`cm_met`)) : esc(t(`cm_missed`))}</span>`;

            const insights = Array.isArray(s.insights) ? s.insights : [];
            const insightsHtml = insights.length
                ? `<ul class="scr-cm-insights">` + insights.map((x) => `<li>${esc(x)}</li>`).join(``) + `</ul>`
                : ``;

            return `
                <div class="scr-cm scr-cm-${tone}">
                    <div class="scr-cm-head">
                        <div class="scr-cm-verdict">${verdict}</div>
                        <div class="scr-cm-score"><span class="scr-cm-score-num">${composite}</span><span class="scr-cm-score-max">/100</span><span class="scr-cm-grade">${esc(t(`cm_grade`))} ${grade}</span></div>
                    </div>
                    <div class="scr-cm-kpis">
                        ${kpi(esc(t(`cm_kpi_csi`)), Math.round(Number(s.csi) || 0), !!s.improved)}
                        ${kpi(esc(t(`cm_kpi_retention`)), num1(Number(s.retention) || 0) + `%`, !!s.retainedWell)}
                        ${kpi(esc(t(`cm_kpi_employ`)), Math.round(Number(s.employ) || 0), !!s.employable)}
                        ${kpi(esc(t(`cm_kpi_wellbeing`)), Math.round(Number(s.wellbeing) || 0), !!s.well)}
                    </div>
                    <div class="scr-cm-rev">${esc(t(`cm_net_saving`))}: <strong>${savingStr}</strong> <span>${esc(t(`cm_saving_note`))}</span></div>
                    <div class="scr-cm-gates-h">${esc(t(`cm_gates_heading`))}</div>
                    <div class="scr-cm-gates">
                        ${chip(!!s.improved, esc(t(`cm_gate_csi`)))}
                        ${chip(!!s.retainedWell, esc(t(`cm_gate_retention`)))}
                        ${chip(!!s.employable, esc(t(`cm_gate_employ`)))}
                        ${chip(!!s.well, esc(t(`cm_gate_wellbeing`)))}
                    </div>
                    <div class="scr-cm-insights-h">${esc(t(`cm_insights_heading`))}</div>
                    ${insightsHtml}
                </div>
            `;
        }

        getHint(state, results) {
            if (!results) return null;
            const ds = state.domainState;
            if (ds.tunnelVisionRun) return window.mySimulation.t(`hint_tunnel`);
            if (ds.hoardingRun) return window.mySimulation.t(`hint_hoarding`);
            if (ds.trainingAllRun) return window.mySimulation.t(`hint_training`);
            if (ds.grievance >= 65) return window.mySimulation.t(`hint_grievance`);
            if (ds.zeroSumRun) return window.mySimulation.t(`hint_zerosum`);
            if (ds.csi >= (ds.baseline + 12) && ds.employ >= 62 && ds.wellbeing >= 60) return window.mySimulation.t(`hint_strong`);
            return null;
        }

        getHistoryTableConfig() {
            return [
                { key: `period`, label: `Round`, i18nKey: `col_round` },
                { key: `results.summary`, label: `Move`, i18nKey: `col_move` },
                { key: `results.csi`, label: `CSI`, i18nKey: `col_csi`, formatter: (v) => `${Math.round(v)}` },
                { key: `results.retention`, label: `Retention`, i18nKey: `col_retention`, formatter: (v) => `${Math.round(v)}%` },
                { key: `results.employ`, label: `Employability`, i18nKey: `col_employ`, formatter: (v) => `${Math.round(v)}` },
                { key: `results.wellbeing`, label: `Wellbeing`, i18nKey: `col_wellbeing`, formatter: (v) => `${Math.round(v)}` }
            ];
        }

        getPresets() { return null; }

        _updateBriefing(state) {
            const idx = Math.min((state.currentPeriod || 1) - 1, this.ROUNDS.length - 1);
            const round = this.ROUNDS[idx];
            const t = window.mySimulation ? window.mySimulation.t.bind(window.mySimulation) : (k) => k;

            const titleEl = document.getElementById(`briefingTitle`);
            if (titleEl) titleEl.textContent = t(round.titleKey);
            const textEl = document.getElementById(`briefingText`);
            if (textEl) textEl.innerHTML = t(round.textKey);
            const nameEl = document.getElementById(`roundNameDisplay`);
            if (nameEl) nameEl.textContent = t(round.nameKey);
            const clockEl = document.getElementById(`clockDisplay`);
            if (clockEl) clockEl.textContent = t(round.clockKey);

            for (let i = 0; i < this.ROUNDS.length; i++) {
                const panel = document.getElementById(this.ROUNDS[i].panelId);
                if (panel) panel.style.display = (i === idx) ? `block` : `none`;
            }
        }

